DROP TABLE IF EXISTS `eventos_partido`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `eventos_partido` (
  `id` int NOT NULL AUTO_INCREMENT,
  `partido_id` int NOT NULL,
  `equipo_id` int DEFAULT NULL,
  `jugador_id` int DEFAULT NULL,
  `jugador_asistente_id` int DEFAULT NULL,
  `tipo_evento` varchar(50) NOT NULL,
  `minuto_o_periodo` varchar(20) NOT NULL,
  `valor_puntos` int DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `comentario` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `partido_id` (`partido_id`),
  KEY `equipo_id` (`equipo_id`),
  KEY `jugador_id` (`jugador_id`),
  KEY `jugador_asistente_id` (`jugador_asistente_id`),
  CONSTRAINT `eventos_partido_ibfk_1` FOREIGN KEY (`partido_id`) REFERENCES `partidos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `eventos_partido_ibfk_2` FOREIGN KEY (`equipo_id`) REFERENCES `equipos` (`id`),
  CONSTRAINT `eventos_partido_ibfk_3` FOREIGN KEY (`jugador_id`) REFERENCES `jugadores` (`id`),
  CONSTRAINT `eventos_partido_ibfk_4` FOREIGN KEY (`jugador_asistente_id`) REFERENCES `jugadores` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1500 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
