--
-- Table structure for table `partidos`
--

DROP TABLE IF EXISTS `partidos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `partidos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `torneo_id` int NOT NULL,
  `jornada` int NOT NULL DEFAULT '1',
  `fase_id` int DEFAULT NULL,
  `grupo_id` int DEFAULT NULL,
  `cancha_id` int DEFAULT NULL,
  `equipo_local_id` int NOT NULL,
  `equipo_visitante_id` int NOT NULL,
  `puntos_local` int DEFAULT '0',
  `puntos_visitante` int DEFAULT '0',
  `estado` enum('PROGRAMADO','EN_JUEGO','FINALIZADO','CANCELADO') DEFAULT 'PROGRAMADO',
  `estado_detalle` varchar(50) DEFAULT NULL,
  `minuto_actual` int DEFAULT NULL,
  `fecha_hora` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `torneo_id` (`torneo_id`),
  KEY `cancha_id` (`cancha_id`),
  KEY `equipo_local_id` (`equipo_local_id`),
  KEY `equipo_visitante_id` (`equipo_visitante_id`),
  KEY `fk_partidos_fases` (`fase_id`),
  KEY `fk_partidos_grupos` (`grupo_id`),
  CONSTRAINT `fk_partidos_grupos` FOREIGN KEY (`grupo_id`) REFERENCES `grupos` (`id`),
  CONSTRAINT `partidos_ibfk_1` FOREIGN KEY (`torneo_id`) REFERENCES `torneos` (`id`),
  CONSTRAINT `partidos_ibfk_2` FOREIGN KEY (`cancha_id`) REFERENCES `canchas` (`id`),
  CONSTRAINT `partidos_ibfk_3` FOREIGN KEY (`equipo_local_id`) REFERENCES `equipos` (`id`),
  CONSTRAINT `partidos_ibfk_4` FOREIGN KEY (`equipo_visitante_id`) REFERENCES `equipos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=145 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

