CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_obtener_fixture_torneo`(
    IN p_torneo_id INT
)
BEGIN
    SELECT 
        p.id AS partido_id,
        el.nombre AS equipo_local,
        p.puntos_local,
        ev.nombre AS equipo_visitante,
        p.puntos_visitante,
        c.nombre AS cancha,
        p.estado,
        DATE_FORMAT(p.fecha_hora, '%d/%m/%Y %H:%i') AS fecha_hora_formateada
    FROM partidos p
    JOIN equipos el ON p.equipo_local_id = el.id
    JOIN equipos ev ON p.equipo_visitante_id = ev.id
    JOIN canchas c ON p.cancha_id = c.id
    WHERE p.torneo_id = p_torneo_id
    ORDER BY p.fecha_hora ASC;
END ;;
